  alternativas:[{id:"A",texto:"LDL elevado, resistência insulínica, hipertensão arterial sistêmica"},{id:"B",texto:"HDL baixo, hipertrigliceridemia, diabetes"},{id:"C",texto:"LDL elevado, hipertrigliceridemia, hipertensão arterial sistêmica"},{id:"D",texto:"insuficiência cardíaca, diabetes e hipertensão arterial sistêmica"},{id:"E",texto:"esteatose hepática, hipertrigliceridemia, diabetes"}],
